        for c in range(cols):
            val = grid[r][c]

            if val != 0:  # Non-background color
                # Check if this cell has NO right neighbor of same color OR is at grid edge
                has_right_same = False
                if c < cols - 1 and grid[r][c+1] == val:
                    has_right_same = True

                # If no right neighbor of same color (or at edge), check about being isolated
                if not has_right_same:
                    # This cell should become 1 if it's part of a pattern that ends/isolated
                    # Check if it's the last of its color in this row segment
                    next_diff = c + 1
                    while next_diff < cols and (grid[r][next_diff] == val or grid[r][next_diff] == 0):
                        next_diff += 1
                    # Only if we're at edge or about to change color significantly
                    if next_diff >= cols or (c >= cols - 1 or grid[r][c+1] == 0):
                        result[r][c] = 1

            else:  # 0 value (background or potential convert)
                # 0s convert to 1 when they form pattern after different non-zero
                # If preceded by non-0, and following a changing pattern
                # Check if this 0 is part of a "patternizing" section
                prev_val = grid[r][c-1] if c > 0 else None

                if prev_val is not None and prev_val != 0 and c > 0:
                    # 0 after different non-zero - check pattern
                    # Count consecutive 0s
                    zero_run = 0
                    k = c
                    while k < cols and grid[r][k] == 0:
                        k += 1
                        zero_run += 1

                    # If followed by different non-zero (not 9/3/etc of same type), patternize them
                    if k < cols and grid[r][k] != 0 and grid[r][k] != prev_val:
                        for z in range(c, c + zero_run):
